package ec.edu.ucacue.odontocare.treatment.presentation;import java.util.List;import jakarta.validation.Valid;import jakarta.validation.constraints.*;public record TreatmentPlanRequest(@NotBlank @Size(max=160)String title,@NotEmpty List<@Valid Item> items){public record Item(@Pattern(regexp="TOOTH_(0[1-9]|[12][0-9]|3[0-6])")String pieceCode,@NotBlank @Size(max=500)String description,@Min(1)@Max(5)short priority,@Min(1)@Max(99)short sessionsEstimated,@Size(max=4000)String observations){}}
